def rule_argued_or_submitted_date_header(doc: dict) -> list[dict]:
    try:
        month_pat = (
            r"(?:January|February|March|April|May|June|July|August|"
            r"September|October|November|December)"
        )
        date_pat = rf"{month_pat}\s+\d{{1,2}},\s+\d{{4}}"
        header_patterns = (
            re.compile(
                rf"^\s*(Argued\s+and\s+Submitted(?:\s+En\s+Banc)?\s+{date_pat}(?:\s*\*+)?)\s*$",
                re.IGNORECASE,
            ),
            re.compile(
                rf"^\s*(Submitted(?:\s+on\s+the\s+briefs)?(?:\s+En\s+Banc)?\s+{date_pat}(?:\s*\*+)?)\s*$",
                re.IGNORECASE,
            ),
            re.compile(
                rf"^\s*(Argued(?:\s+En\s+Banc)?\s+{date_pat}(?:\s*\*+)?)\s*$",
                re.IGNORECASE,
            ),
        )
        negative_prefixes = (
            "submission deferred",
            "submission vacated",
            "submission withdrawn",
            "resubmitted",
        )

        def _intish(value, default):
            try:
                return int(value)
            except Exception:
                return default

        def _clean(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "").replace("\x0c", " ")).strip()

        def _extract(text: str) -> str | None:
            cleaned = _clean(text)
            if not cleaned:
                return None
            lowered = cleaned.lower()
            if lowered.startswith(negative_prefixes):
                return None
            for pattern in header_patterns:
                match = pattern.match(cleaned)
                if match:
                    return match.group(1).strip()
            return None

        def _scan_items(items: list[dict], line_field: str, limit: int) -> list[dict]:
            ordered = sorted(
                [item for item in (items or []) if isinstance(item, dict)],
                key=lambda item: (
                    _intish(item.get("page_no"), 10**9),
                    _intish(item.get(line_field), 10**9),
                ),
            )
            scan_limit = min(len(ordered), limit)
            for i in range(scan_limit):
                item = ordered[i]
                text = _clean(item.get("text", ""))
                if not text:
                    continue

                for end in range(i + 1, min(i + 4, scan_limit + 1)):
                    combined = " ".join(
                        _clean(ordered[j].get("text", ""))
                        for j in range(i, end)
                        if _clean(ordered[j].get("text", ""))
                    )
                    match_text = _extract(combined)
                    if not match_text:
                        continue
                    span = {"text": match_text}
                    if item.get("page_no") is not None:
                        span["page_no"] = item.get("page_no")
                    if item.get(line_field) is not None:
                        span[line_field] = item.get(line_field)
                    return [span]
            return []

        line_hits = _scan_items(doc.get("lines") or [], "line_no", 320)
        if line_hits:
            return line_hits

        paragraph_hits = _scan_items(doc.get("paragraphs") or [], "paragraph_no", 160)
        if paragraph_hits:
            return paragraph_hits

        full_text = (doc.get("text") or "").replace("\x0c", " ")
        top_blob = full_text[:25000]
        matches = []
        for pattern in header_patterns:
            for match in pattern.finditer(top_blob):
                matches.append((match.start(), match.group(1).strip()))
        if matches:
            matches.sort(key=lambda item: item[0])
            return [{"text": matches[0][1]}]

        return []
    except Exception:
        return []

import re


def rule_argument_date_order_phrase(doc: dict) -> list[dict]:
    try:
        month_pat = (
            r"(?:January|February|March|April|May|June|July|August|"
            r"September|October|November|December)"
        )
        date_pat = rf"{month_pat}\s+\d{{1,2}},\s+\d{{4}}"
        phrase_patterns = (
            re.compile(
                rf"\bwe\s+heard\s+oral\s+argument(?:\s+in\s+this\s+case)?"
                rf"(?:\s+on\s+an\s+expedited\s+basis)?\s+on\s+({date_pat})\b",
                re.IGNORECASE,
            ),
            re.compile(
                rf"\bwe\s+held\s+argument\s+on\s+the\s+merits\s+on\s+({date_pat})\b",
                re.IGNORECASE,
            ),
            re.compile(
                rf"\boral\s+argument\s+scheduled\s+for\s+({date_pat})\b",
                re.IGNORECASE,
            ),
        )

        def _intish(value, default):
            try:
                return int(value)
            except Exception:
                return default

        def _clean(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "").replace("\x0c", " ")).strip()

        lines = sorted(
            [item for item in (doc.get("lines") or []) if isinstance(item, dict)],
            key=lambda item: (
                _intish(item.get("page_no"), 10**9),
                _intish(item.get("line_no"), 10**9),
            ),
        )

        limit = min(len(lines), 120)
        for i in range(limit):
            window = " ".join(
                _clean(lines[j].get("text", ""))
                for j in range(i, min(i + 5, limit))
                if _clean(lines[j].get("text", ""))
            )
            if not window:
                continue
            for pattern in phrase_patterns:
                match = pattern.search(window)
                if not match:
                    continue
                span = {"text": match.group(1).strip()}
                if lines[i].get("page_no") is not None:
                    span["page_no"] = lines[i].get("page_no")
                if lines[i].get("line_no") is not None:
                    span["line_no"] = lines[i].get("line_no")
                return [span]

        paragraphs = sorted(
            [item for item in (doc.get("paragraphs") or []) if isinstance(item, dict)],
            key=lambda item: (
                _intish(item.get("page_no"), 10**9),
                _intish(item.get("paragraph_no"), 10**9),
            ),
        )
        for item in paragraphs[:40]:
            text = _clean(item.get("text", ""))
            if not text:
                continue
            for pattern in phrase_patterns:
                match = pattern.search(text)
                if not match:
                    continue
                span = {"text": match.group(1).strip()}
                if item.get("page_no") is not None:
                    span["page_no"] = item.get("page_no")
                if item.get("paragraph_no") is not None:
                    span["paragraph_no"] = item.get("paragraph_no")
                return [span]

        top_blob = (doc.get("text") or "").replace("\x0c", " ")[:16000]
        for pattern in phrase_patterns:
            match = pattern.search(top_blob)
            if match:
                return [{"text": match.group(1).strip()}]

        return []
    except Exception:
        return []

def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


